/**
 * ATDD RED-PHASE — Story 11-2, AC1 (no fabricated session under tests/).
 * Generated by `/bmad-tea AT 11-2` (Murat) 2026-10-13.
 *
 * BEHAVIORAL RED NOW: `auth.setup.ts` still fabricates a session
 * (`classlite_session=stub-...` via `context.addCookies`). Both assertions below
 * FAIL against today's tree and go GREEN once Task 2 replaces the fabrication
 * with a real `POST /api/auth/login`. This is a real red-by-assertion (not an
 * import-fail), so it stays green permanently as a regression guard.
 *
 * TWO ORACLES (party-mode, Murat): a literal grep alone false-greens on a rename.
 *   (1) STRUCTURAL — no file under tests/ passes a SESSION-shaped cookie to
 *       context.addCookies (the harness legitimately still writes only `lang`).
 *   (2) TRIPWIRE — the retired literal stub string appears nowhere under tests/.
 *
 * SELF-MATCH GUARD: this file is excluded from the scan, and the literal needle
 * is assembled from fragments so the guard does not match itself.
 *
 * ENVIRONMENT NOTE: default jsdom env; uses node:fs/node:path only.
 */
import { readdirSync, readFileSync, statSync } from 'node:fs'
import { basename, join, resolve } from 'node:path'
import { describe, expect, it } from 'vitest'

const TESTS_ROOT = resolve(__dirname, '../..') // classlite-web/tests
const SELF = basename(__filename) // exclude this guard from its own scan
// Assembled so this guard file does not self-match the tripwire.
const RETIRED_STUB = ['stub', 'session', 'token', 'for', 'phase', '0'].join('-')

function walk(dir: string): string[] {
  const out: string[] = []
  for (const name of readdirSync(dir)) {
    const full = join(dir, name)
    if (statSync(full).isDirectory()) out.push(...walk(full))
    else if (/\.(ts|tsx)$/.test(name) && basename(full) !== SELF) out.push(full)
  }
  return out
}

const files = walk(TESTS_ROOT)

describe('11-2 AC1 — no fabricated session remains under tests/', () => {
  it('(tripwire) the retired stub token string appears in no test file', () => {
    const offenders = files.filter((f) =>
      readFileSync(f, 'utf8').includes(RETIRED_STUB),
    )
    expect(
      offenders.map((f) => f.replace(TESTS_ROOT, 'tests')),
      'retired stub token must be fully removed (AC1)',
    ).toEqual([])
  })

  it('(structural) no test passes a session-shaped cookie to context.addCookies', () => {
    // A session cookie is `classlite_session` or `refresh_token`. The harness may
    // only ADD the non-auth `lang` cookie; real sessions must come from a 200
    // Set-Cookie on /api/auth/login (captured via request.storageState), never
    // fabricated via addCookies.
    const sessionCookieNames = /(classlite_session|refresh_token)/
    const CALL = 'addCookies'
    const offenders: string[] = []
    for (const f of files) {
      const text = readFileSync(f, 'utf8')
      // Extract each addCookies(...) call's FULL argument list by paren-depth
      // matching. A non-greedy `addCookies\(([\s\S]*?)\)` regex truncates at the
      // FIRST inner `)` — e.g. a nested call like `name: resolve()` — and would
      // let a session cookie named after that paren slip the guard. Depth
      // matching captures the whole call. Green-phase: cookie-sharing.spec READS
      // refresh_token via context.cookies(), which is fine — only addCookies(...)
      // is forbidden.
      for (let at = text.indexOf(`${CALL}(`); at !== -1; at = text.indexOf(`${CALL}(`, at + 1)) {
        let depth = 0
        let end = text.length
        for (let i = at + CALL.length; i < text.length; i++) {
          if (text[i] === '(') depth++
          else if (text[i] === ')' && --depth === 0) {
            end = i + 1
            break
          }
        }
        if (sessionCookieNames.test(text.slice(at, end))) {
          offenders.push(f.replace(TESTS_ROOT, 'tests'))
          break // one offense per file is enough
        }
      }
    }
    expect(
      offenders,
      'session cookies must be captured from real login, never fabricated via addCookies (AC1)',
    ).toEqual([])
  })
})
